import os
MODULES=['pcc_neuro_ext92','pcc_pediatric_neuro_ext81','pcc_pediatric_surg_ext81']
FUNCS={
'pcc_neuro_ext92':[('TeleStrokeThrombectomyExt','0.15 + Number(input.travel||30)*0.01 + Number(input.lkw||4)*0.05 + Number(input.thrombectomy||1)*0.2'),('MobileStrokeUnitExt','0.2 + Number(input.travel||15)*0.01 + Number(input.scenesCT||1)*0.3 + Number(input.tPA||1)*0.2'),('TelestrokeOutcomeExt','0.18 + Number(input.thrombolysis||1)*0.2 + Number(input.thrombectomy||1)*0.2 + Number(input.mrs||2)*0.1'),('IVTriageExt','0.15 + Number(input.doorToNeedle||30)*-0.005 + Number(input.drt||60)*-0.005 + Number(input.onset||120)*-0.005 + 0.6'),('CTPerfusionSelectionExt','0.2 + Number(input.coreVol||15)*0.02 + Number(input.penumbra||50)*0.005 + Number(input.mismatchRatio||1.8)*0.2'),('LargeVesselOcclusionExt','0.18 + Number(input.drivingScore||5)*0.06 + Number(input.dwi||1)*0.2 + Number(input.collateralPts||3)*0.08'),('DripShipExt','0.2 + Number(input.distance||100)*0.001 + Number(input.tPA||1)*0.2 + Number(input.mothership||1)*0.2'),('DoorInDoorOutExt','0.15 + Number(input.dido||60)*-0.003 + 0.4 + Number(input.transfer||1)*0.2'),('TelestrokeConsentExt','0.2 + Number(input.familyPresent||1)*0.1 + Number(input.signed||1)*0.3 + Number(input.language||1)*0.1'),('NIHSSFollowExt','0.18 + Number(input.nihss||10)*0.03 + Number(input.day||7)*0.04 + Number(input.delta||5)*0.04')],
'pcc_pediatric_neuro_ext81':[('PediatricStrokeExt','0.2 + Number(input.age||5)*0.04 + Number(input.presentation||1)*0.2 + Number(input.imaging||1)*0.2'),('PediatricArteriopathyExt','0.18 + Number(input.type||2)*0.1 + Number(input.recurrent||1)*0.15 + Number(input.collaterals||3)*0.08'),('PediatricStrokeAnticoagExt','0.18 + Number(input.heparin||1)*0.2 + Number(input.warfarin||1)*0.2 + Number(input.lab||2)*0.05'),('PediatricSickleCellStrokeExt','0.18 + Number(input.transfusion||1)*0.2 + Number(input.hydroxyurea||1)*0.2 + Number(input.tcd||1)*0.1'),('PediatricStrokeRehabExt','0.15 + Number(input.intensity||3)*0.1 + Number(input.weeks||12)*0.04 + Number(input.gain||10)*0.04'),('PediatricStrokeRecoveryExt','0.2 + Number(input.mrs||2)*0.1 + Number(input.followMonths||12)*0.02 + Number(input.therapy||3)*0.05'),('PediatricStrokeGeneticExt','0.15 + Number(input.mutations||2)*0.1 + Number(input.syndromic||1)*0.15 + Number(input.familyHist||1)*0.1'),('PediatricNICHExt','0.18 + Number(input.delivery||1)*0.2 + Number(input.asphyxia||1)*0.1 + Number(input.hypothermia||1)*0.2'),('PediatricCVSTExt','0.15 + Number(input.clot||1)*0.2 + Number(input.collaterals||3)*0.08 + Number(input.outcome||1)*0.2'),('PediatricNeuroprotectionExt','0.18 + Number(input.hypothermia||1)*0.2 + Number(input.duration||72)*0.005 + Number(input.outcome||1)*0.2')],
'pcc_pediatric_surg_ext81':[('PediatricDecompressiveHemicraniExt','0.15 + Number(input.age||8)*0.02 + Number(input.ICP||30)*0.01 + Number(input.size||8)*0.05'),('PediatricEDASRevascularizationExt','0.18 + Number(input.age||5)*0.04 + Number(input.donor||1)*0.15 + Number(input.stages||2)*0.1'),('PediatricSTAEDASExt','0.15 + Number(input.age||6)*0.04 + Number(input.graft||1)*0.15 + Number(input.outcome||1)*0.2'),('PediatricSTAEDASBypassExt','0.18 + Number(input.anas||2)*0.1 + Number(input.flow||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricEncephaloduroarterioExt','0.15 + Number(input.age||5)*0.04 + Number(input.trunks||3)*0.06 + Number(input.outcome||1)*0.2'),('PediatricPialSynangiosisExt','0.18 + Number(input.age||6)*0.04 + Number(input.pial||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricEncephalomyosynangiosisSurgExt','0.15 + Number(input.age||7)*0.04 + Number(input.muscle||1)*0.15 + Number(input.outcome||1)*0.2'),('PediatricCerebellarRevascExt','0.15 + Number(input.donor||1)*0.15 + Number(input.posterior||1)*0.2 + Number(input.outcome||1)*0.2'),('PediatricHematomaEvacExt','0.18 + Number(input.location||2)*0.1 + Number(input.vol||20)*0.01 + Number(input.gcs||8)*0.04'),('PediatricResectionMoyaMoyaExt','0.15 + Number(input.age||6)*0.04 + Number(input.type||1)*0.2 + Number(input.outcome||1)*0.2')]}
for m in MODULES:
    d=f'./{m}'
    os.makedirs(d, exist_ok=True)
    eng=f'// filepath: pcc/{m}/{m}_engine.js\n// {m} engine (deterministic)\nmodule.exports.version=\'v3.191.0\';\nmodule.exports.module=\'{m}\';\nmodule.exports.functions={{}};\n'
    for fn,body in FUNCS[m]:
        eng+=f'module.exports.functions[\'{fn}\']=function(input){{const score=Math.round(({body})*100)/100;return{{version:\'v3.191.0\',module:\'{m}\',function:\'{fn}\',input,score,ts:new Date().toISOString()}};}};\n'
    eng+=f'\n// TS: v3.191.0\n'
    open(f'{d}/{m}_engine.js','w',encoding='utf-8').write(eng)
    test=f'// filepath: pcc/{m}/{m}_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;for(const fn of Object.keys(F)){{const r=F[fn]({{}});if(typeof r.score===\'number\'&&r.score>=0&&r.score<=1.5)pass++;else console.error(\'FAIL\',fn,r);}}console.log(\'{m} unit:\',pass,\'passed\');if(pass!==10)process.exit(1);\n'
    open(f'{d}/{m}_test.js','w',encoding='utf-8').write(test)
    itest=f'// filepath: pcc/{m}/{m}_integration_test.js\nconst {{functions:F}}=require(\'./{m}_engine\');let pass=0;const samples=[{{value:1}},{{value:2}},{{value:3}},{{value:4}},{{value:5}}];for(const fn of Object.keys(F)){{for(const s of samples){{const r=F[fn](s);if(r&&typeof r.score===\'number\')pass++;}}}}console.log(\'{m} integration:\',pass,\'passed\');if(pass!==50)process.exit(1);\n'
    open(f'{d}/{m}_integration_test.js','w',encoding='utf-8').write(itest)
    routes=f'// filepath: pcc/{m}/{m}_routes.js\nconst express=require(\'express\');const {{functions:F}}=require(\'./{m}_engine\');const {{authenticate}}=require(\'../middleware\');const router=express.Router();\nrouter.get(\'/list\',(_req,res)=>res.json({{module:\'{m}\',version:\'v3.191.0\',functions:Object.keys(F)}}));\nrouter.post(\'/call/:fn\',(req,res)=>{{const fn=req.params.fn;if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](req.body||{{}});res.json(r);}});\nrouter.post(\'/record\',(req,res)=>{{const {{fn,payload,decisionId}}=req.body||{{}};if(!F[fn])return res.status(404).json({{error:\'not found\'}});const r=F[fn](payload||{{}});res.json({{decisionId,...r}});}});\nmodule.exports=router;\n'
    open(f'{d}/{m}_routes.js','w',encoding='utf-8').write(routes)
    sql=f'-- pcc/{m}/{m}_up.sql\nIF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N\'[dbo].[{m}]\') AND type = \'U\')\nBEGIN\nCREATE TABLE [dbo].[{m}] (\n  [id] INT IDENTITY(1,1) PRIMARY KEY,\n  [tenant_id] NVARCHAR(64) NOT NULL,\n  [version] NVARCHAR(16) NOT NULL,\n  [module] NVARCHAR(64) NOT NULL,\n  [function] NVARCHAR(128) NOT NULL,\n  [input] NVARCHAR(MAX) NULL,\n  [score] DECIMAL(6,2) NULL,\n  [ts] DATETIME2 DEFAULT SYSUTCDATETIME()\n);\nEND\n'
    open(f'{d}/{m}_up.sql','w',encoding='utf-8').write(sql)
    print(f'{m}: 5 files written')
print('P3-IK v3.191.0: 16 files written')
